topByCalls.query:
/* NOTE: This metric assumes the primary is online. If it is not online, then don't use this metric. */
SELECT
  CASE
    -- Primaries do not have replication delay, so report 0
    WHEN NOT pg_catalog.pg_is_in_recovery() THEN $1
    WHEN pg_catalog.pg_last_wal_receive_lsn() IS NOT DISTINCT FROM pg_catalog.pg_last_wal_replay_lsn() THEN $2
    ELSE GREATEST($3, EXTRACT ($4 FROM (pg_catalog.now() - GREATEST(
          /* approx commit time of the latest commit that was applied. depends on commits happening on primary */
          pg_catalog.pg_last_xact_replay_timestamp(),
          /* approx finish time of last checkpoint. depends only on primary being online */
          (SELECT checkpoint_time FROM pg_catalog.pg_control_checkpoint())
    ))))
  END AS replication_delay_seconds

